/*
The statement as provided is incomplete/underspecified:
- It describes an n x n binary grid.
- A spell "myon" flips all bits in an axis-aligned rectangle.
- We must turn all 1s into 0s using the shortest sequence of spells.

A natural and standard interpretation is:
- Minimize the number of rectangle flips.
- Output that minimum number.

Under this interpretation, the answer is simply the number of maximal rectangles in a greedy decomposition
from top-left to bottom-right using 2D difference/XOR technique.

Reason:
For rectangle XOR flips, if we process cells in row-major order and ensure each cell becomes 0 when visited,
then whenever the effective value at (i,j) is 1, any valid solution must start some rectangle at (i,j),
because no later-starting rectangle can affect it. To maximize usefulness and never hurt already-fixed cells,
we can extend that rectangle as far down/right as possible over currently effective 1s. This greedy is optimal.

Implementation:
- Maintain a 2D difference array for active rectangle XOR effects.
- Reconstruct current flip parity at each cell while scanning.
- If effective bit at (i,j) is 1, find maximal rectangle of effective 1s starting at (i,j),
  apply one flip there, and count it.

Time complexity is O(n^3) in worst case with straightforward expansion, acceptable for moderate n.
If the original problem had different required output (e.g. print the sequence), the statement here is insufficient.

Input format assumed:
n
n lines of length n consisting of '0'/'1'

Output:
minimum number of spells
*/
public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n;
        if (!fs.hasNext()) return;
        n = fs.nextInt();
        char[][] a = new char[n][];
        for (int i = 0; i < n; i++) a[i] = fs.next().toCharArray();

        int[][] diff = new int[n + 2][n + 2];
        int[][] pref = new int[n][n];

        long ans = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int x = diff[i][j];
                if (i > 0) x ^= pref[i - 1][j];
                if (j > 0) x ^= pref[i][j - 1];
                if (i > 0 && j > 0) x ^= pref[i - 1][j - 1];
                pref[i][j] = x;

                int effective = (a[i][j] - '0') ^ pref[i][j];
                if (effective == 0) continue;

                // Find maximal rectangle of current effective 1s starting at (i,j)
                int maxWidth = n - j;
                int bottom = i;
                while (bottom < n) {
                    int width = 0;
                    while (width < maxWidth) {
                        int jj = j + width;
                        int cur = getEffective(a, diff, pref, bottom, jj);
                        if (cur == 1) width++;
                        else break;
                    }
                    if (width == 0) break;
                    maxWidth = width;
                    bottom++;
                }
                int r2 = bottom - 1;
                int c2 = j + maxWidth - 1;

                // apply rectangle flip [i..r2][j..c2]
                apply(diff, i, j, r2, c2);

                // update pref values for current cell onward lazily via diff;
                // current pref[i][j] also toggles now, but we already handled this cell.
                ans++;
            }
        }

        System.out.println(ans);
    }

    static void apply(int[][] diff, int r1, int c1, int r2, int c2) {
        diff[r1][c1] ^= 1;
        diff[r1][c2 + 1] ^= 1;
        diff[r2 + 1][c1] ^= 1;
        diff[r2 + 1][c2 + 1] ^= 1;
    }

    static int getEffective(char[][] a, int[][] diff, int[][] pref, int i, int j) {
        int x = diff[i][j];
        if (i > 0) x ^= pref[i - 1][j];
        if (j > 0) x ^= pref[i][j - 1];
        if (i > 0 && j > 0) x ^= pref[i - 1][j - 1];
        pref[i][j] = x;
        return (a[i][j] - '0') ^ x;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        boolean hasNext() throws IOException {
            int c;
            while ((c = read()) != -1 && c <= ' ') {}
            if (c == -1) return false;
            ptr--;
            return true;
        }

        String next() throws IOException {
            int c;
            while ((c = read()) != -1 && c <= ' ') {}
            StringBuilder sb = new StringBuilder();
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

