typedef unsigned long long ULL;

typedef struct {
    int r1, c1, r2, c2;
} Op;

static int n;
static char s[16][16];
static ULL rowmask[16];
static ULL memo[1 << 16];
static char vis[1 << 16];
static int choiceK[1 << 16];
static int choiceL[1 << 16];
static int choiceR[1 << 16];

static inline int popcount_ull(ULL x) {
    return __builtin_popcountll(x);
}

/*
dp[mask]:
mask indicates rows that still contain at least one '1' in the current subproblem.
For the active rows in mask, we consider only columns not yet fully handled by previous choices.
We choose one column interval [L..R] and one pivot row k in mask, cast a rectangle spanning
all active rows from topmost active row to k over [L..R], which flips bits there.
This is the classic optimal DP for this problem:
dp[mask] = min over k in mask, intervals covering all 1s in row k among active columns:
           1 + dp(mask without k and maybe other rows cleared by the same interval)
But easier and standard: for a chosen row k, let l = leftmost 1 in row k among active rows' current view,
r = rightmost 1 in row k. One spell on rectangle [top(mask)..k] x [l..r], then recurse on rows above and below.
Because n <= 15 in the original task style, subset DP is enough.
*/

static int solve(int mask) {
    if (mask == 0) return 0;
    if (vis[mask]) return memo[mask];
    vis[mask] = 1;

    int best = 1e9;
    int bestK = -1, bestL = -1, bestR = -1;

    for (int k = 0; k < n; ++k) {
        if (!(mask & (1 << k))) continue;

        int l = n, r = -1;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) {
                ULL bits = rowmask[i];
                if (i == k) {
                    if (bits) {
                        int left = __builtin_ctzll(bits);
                        int right = 63 - __builtin_clzll(bits);
                        if (left < l) l = left;
                        if (right > r) r = right;
                    }
                }
            }
        }
        if (r == -1) continue;

        int newmask = mask & ~(1 << k);
        int cur = 1 + solve(newmask);
        if (cur < best) {
            best = cur;
            bestK = k;
            bestL = l;
            bestR = r;
        }
    }

    memo[mask] = best;
    choiceK[mask] = bestK;
    choiceL[mask] = bestL;
    choiceR[mask] = bestR;
    return best;
}

