import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = []
    idx = 1
    for _ in range(n):
        s = data[idx].strip()
        idx += 1
        if len(s) == n and all(c in '01' for c in s):
            a.append([int(c) for c in s])
        else:
            # Fallback if row is space-separated digits
            row = [int(s)]
            while len(row) < n:
                row.append(int(data[idx]))
                idx += 1
            a.append(row)

    # dp[i][j]: minimum number of rectangle flips to make submatrix
    # rows [0..i], cols [0..j] all zero.
    #
    # Standard recurrence:
    # If a[i][j] == 0, dp[i][j] can be covered by smaller prefixes.
    # If a[i][j] == 1, one optimal move is flipping some rectangle
    # [x..i] x [y..j] ending at (i,j), which leads to:
    # dp[i][j] = 1 + min(dp[x-1][j], dp[i][y-1]) over choices,
    # and this simplifies to:
    #   if a[i][j] == 1:
    #       dp[i][j] = 1 + min(min_{k<i} dp[k][j], min_{k<j} dp[i][k])
    #   else:
    #       dp[i][j] = min(min_{k<i} dp[k][j], min_{k<j} dp[i][k])
    #
    # With borders handled by considering empty prefix cost 0.

    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            best = 10**9

            if i > 0:
                for k in range(i):
                    if dp[k][j] < best:
                        best = dp[k][j]
            if j > 0:
                for k in range(j):
                    if dp[i][k] < best:
                        best = dp[i][k]

            if best == 10**9:
                best = 0

            dp[i][j] = best + (1 if a[i][j] == 1 else 0)

    print(dp[n-1][n-1])

if __name__ == "__main__":
    solve()

