/*
The statement is incomplete about input/output format for the sequence,
but the core task is standard:

Given an n x n binary matrix, one operation chooses any axis-aligned rectangle
and flips all bits inside it. We need to transform the matrix into all zeros
using the minimum number of rectangle flips, and output one such sequence.

Key fact:
Any binary matrix can be represented uniquely as XOR-sum of suffix rectangles
(i..n, j..n). If we process cells from bottom-right to top-left, whenever the
current effective value at (i,j) is 1, we must flip rectangle (i,j)-(n,n).
This is optimal and unique.

To implement efficiently, use a 2D difference / prefix-XOR accumulator while
scanning from bottom-right to top-left.

Assumed output format:
- first line: minimum number of spells
- then for each spell: r1 c1 r2 c2   (1-indexed)

If the judge expects only the number, this still may fail, but the problem asks
for the sequence, so this is the natural format.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
        a[i] = " " + a[i];
    }

    // pref[i][j] = XOR of chosen suffix-rectangle starts in submatrix [i..n][j..n]
    vector<vector<int>> pref(n + 2, vector<int>(n + 2, 0));
    vector<array<int,4>> ops;

    for (int i = n; i >= 1; --i) {
        for (int j = n; j >= 1; --j) {
            int curFlip = pref[i + 1][j] ^ pref[i][j + 1] ^ pref[i + 1][j + 1];
            int curVal = (a[i][j] - '0') ^ curFlip;
            if (curVal == 1) {
                // Need to flip suffix rectangle (i,j)-(n,n)
                ops.push_back({i, j, n, n});
                pref[i][j] = curFlip ^ 1;
            } else {
                pref[i][j] = curFlip;
            }
        }
    }

    cout << ops.size() << '\n';
    for (auto &op : ops) {
        cout << op[0] << ' ' << op[1] << ' ' << op[2] << ' ' << op[3] << '\n';
    }

    return 0;
}
